function flattenToDepth(arr: any[], n: number): any[] {
  const out: any[] = [];
  const walk = (items: any[], budget: number) => {
    for (const x of items) {
      if (Array.isArray(x) && budget > 0) walk(x, budget - 1);
      else out.push(x);
    }
  };
  walk(arr, n);
  return out;
}

