function flattenToDepth(arr: any[], n: number): any[] {
  const out: any[] = [];
  const stack: [any[], number, number][] = [[arr, 0, 0]];
  while (stack.length) {
    const top = stack[stack.length - 1];
    const [items, i, depth] = top;
    if (i === items.length) { stack.pop(); continue; }
    top[1] = i + 1;
    const x = items[i];
    if (Array.isArray(x) && depth < n) stack.push([x, 0, depth + 1]);
    else out.push(x);
  }
  return out;
}

